// ── Persist bookings & users across page loads ───────────────
(function _rehydrateDB() {
  const SEED_BOOKING_IDS = new Set(['BK001','BK002','BK003','BK004','BK005']);
  const SEED_USER_IDS    = new Set(['U001','U002','U003','U004','U005','U006']);
  try {
    const saved = JSON.parse(localStorage.getItem('lf_bookings') || '[]');
    if (Array.isArray(saved)) {
      saved.forEach(b => { if (!SEED_BOOKING_IDS.has(b.id) && !_DB.bookings.find(x => x.id === b.id)) _DB.bookings.push(b); });
    }
  } catch (_) {}
  try {
    const savedUsers = JSON.parse(localStorage.getItem('lf_users') || '[]');
    if (Array.isArray(savedUsers)) {
      savedUsers.forEach(u => { if (!SEED_USER_IDS.has(u.id) && !_DB.users.find(x => x.email === u.email)) _DB.users.push(u); });
    }
  } catch (_) {}
})();

// ── API helpers (in-memory, instant, no network) ─────────────
async function apiFetch(path) {
  // Kept for compatibility but not used directly any more
  return Promise.resolve([]);
}

async function getAirports() {
  const res = await fetch('/api/airports');
  if (!res.ok) throw new Error('Failed to fetch airports');
  return res.json();
}

async function getFlights(params = {}) {
  const q = new URLSearchParams();
  if (params.origin)      q.set('origin',      params.origin);
  if (params.destination) q.set('destination', params.destination);
  if (params.cabinClass)  q.set('cabinClass',  params.cabinClass);
  const res = await fetch('/api/flights' + (q.toString() ? '?' + q.toString() : ''));
  if (!res.ok) throw new Error('Failed to fetch flights');
  return res.json();
}

async function getFlight(id) {
  const res = await fetch(`/api/flights/${id}`);
  if (!res.ok) throw new Error(`Flight ${id} not found`);
  return res.json();
}

async function createBooking(booking) {
  const res = await fetch('/api/bookings', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(booking),
  });
  if (!res.ok) throw new Error('Failed to create booking');
  return res.json();
}

// ── MSW readiness helper ─────────────────────────────────────
// Returns a promise that resolves once the MSW service worker is active.
// On subsequent page loads the worker is already active, so it resolves
// immediately. On first load it waits for the 'msw:ready' event.
function waitForMSW() {
  if (window.__mswReady) return Promise.resolve();
  return new Promise(resolve => {
    window.addEventListener('msw:ready', resolve, { once: true });
    // Fallback: if MSW never initialises (CDN blocked, etc.) continue after 3s
    setTimeout(resolve, 3000);
  });
}

// ── URL query helpers ────────────────────────────────────────
function getParams() {
  return new URLSearchParams(window.location.search);
}

function buildQuery(obj) {
  const q = new URLSearchParams();
  Object.entries(obj).forEach(([k, v]) => { if (v !== undefined && v !== '') q.set(k, v); });
  return q.toString();
}

// ── Format helpers ───────────────────────────────────────────
function formatPrice(n) {
  return `$${Number(n).toLocaleString('en-AU')}`;
}

function formatDate(iso) {
  if (!iso) return '';
  const [y, m, d] = iso.split('-');
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return `${parseInt(d, 10)} ${months[parseInt(m, 10) - 1]} ${y}`;
}

function todayISO() {
  return new Date().toISOString().slice(0, 10);
}

function tomorrowISO() {
  const d = new Date();
  d.setDate(d.getDate() + 1);
  return d.toISOString().slice(0, 10);
}

// ── Reference ID generator ───────────────────────────────────
function generateRef() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let ref = 'TW-';
  for (let i = 0; i < 6; i++) ref += chars[Math.floor(Math.random() * chars.length)];
  return ref;
}

