function getRegion(airportId) {
  for (const [region, ids] of Object.entries(AIRPORT_REGIONS)) {
    if (ids.includes(airportId)) return region;
  }
  return 'Other';
}

// ── Populate airport dropdowns (grouped by region) ───────────
async function populateAirportSelects(selects, excludeMap = {}) {
  const airports = await getAirports();

  // Group airports by region
  const groups = {};
  airports.forEach(a => {
    const region = getRegion(a.id);
    if (!groups[region]) groups[region] = [];
    groups[region].push(a);
  });

  // Sort regions -  put key tourist destinations first
  const regionOrder = [
    'Australia', 'New Zealand', 'Indonesia / Bali', 'Pacific Islands',
    'Japan', 'China', 'Vietnam', 'Southeast Asia', 'India', 'Middle East',
    'Europe', 'United Kingdom', 'USA', 'Hawaii', 'Canada', 'South America', 'Other'
  ];

  selects.forEach(({ el }) => {
    const current = el.value;
    el.innerHTML = '<option value=""> -  Select airport - </option>';

    regionOrder.forEach(region => {
      const regionAirports = groups[region];
      if (!regionAirports || regionAirports.length === 0) return;

      const group = document.createElement('optgroup');
      group.label = region;

      regionAirports.forEach(a => {
        if (excludeMap[el.id] && excludeMap[el.id] === a.id) return;
        const opt = document.createElement('option');
        opt.value = a.id;
        opt.textContent = `${a.city} (${a.id}) -  ${a.name}`;
        if (a.id === current) opt.selected = true;
        group.appendChild(opt);
      });

      if (group.children.length > 0) el.appendChild(group);
    });
  });

  return airports;
}

// ── Auth helpers ─────────────────────────────────────────────
async function loginUser(email, password) {
  const res = await fetch('/api/auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password }),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || 'Invalid email or password.');
  }
  const safe = await res.json();
  try { localStorage.setItem('lf_user', JSON.stringify(safe)); } catch (_) {}
  return safe;
}

function getCurrentUser() {
  try { return JSON.parse(localStorage.getItem('lf_user') || 'null'); } catch (_) { return null; }
}

function logoutUser() {
  try { localStorage.removeItem('lf_user'); } catch (_) {}
  window.location.href = '/';
}

async function registerUser(data) {
  const res = await fetch('/api/auth/register', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || 'Registration failed.');
  }
  const safe = await res.json();
  try { localStorage.setItem('lf_user', JSON.stringify(safe)); } catch (_) {}
  return safe;
}

async function getCoupons(role) {
  const q = role ? '?role=' + encodeURIComponent(role) : '';
  const res = await fetch('/api/coupons' + q);
  if (!res.ok) throw new Error('Failed to fetch coupons');
  return res.json();
}

const ROLE_LABELS = {
  passenger:       'Passenger',
  travel_agent:    'Travel Agent',
  airline_operator:'Airline Operator',
  admin:           'Admin',
};

const ROLE_DASHBOARD = {
  travel_agent:    'agent-dashboard',
  airline_operator:'operator-dashboard',
  admin:           'admin-dashboard',
};

// Inject auth chip into any page header
function renderAuthNav() {
  const nav = document.querySelector('.header-nav');
  if (!nav) return;
  const user = getCurrentUser();
  const existing = nav.querySelector('[data-testid="nav-auth"]');
  if (existing) existing.remove();
  const wrapper = document.createElement('span');
  wrapper.setAttribute('data-testid', 'nav-auth');
  wrapper.style.cssText = 'display:flex;align-items:center;gap:8px;';
  if (user) {
    const dash = ROLE_DASHBOARD[user.role];
    if (dash) {
      const a = document.createElement('a');
      a.href = dash;
      a.className = 'nav-link';
      a.textContent = 'Dashboard';
      a.setAttribute('data-testid', 'nav-dashboard');
      wrapper.appendChild(a);
    }
    const chip = document.createElement('span');
    chip.className = 'nav-user-chip';
    chip.setAttribute('data-testid', 'nav-user-chip');
    chip.innerHTML = `<span aria-hidden="true">👤</span> ${user.firstName} <span class="nav-role-badge" data-testid="nav-role-badge">${ROLE_LABELS[user.role] || user.role}</span>`;
    wrapper.appendChild(chip);
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'nav-link nav-logout-btn';
    btn.textContent = 'Sign out';
    btn.setAttribute('data-testid', 'btn-logout');
    btn.onclick = logoutUser;
    wrapper.appendChild(btn);
  } else {
    // Build returnTo so auth pages come back to the current page
    const returnTo = encodeURIComponent(window.location.pathname.split('/').pop() + window.location.search);
    const isIndexPage = !window.location.pathname.split('/').pop() || window.location.pathname.endsWith('index.html');
    const authSuffix = isIndexPage ? '' : `?returnTo=${returnTo}`;

    const a = document.createElement('a');
    a.href = `login.html${authSuffix}`;
    a.className = 'btn btn-primary nav-login-btn';
    a.textContent = 'Sign in';
    a.setAttribute('data-testid', 'nav-signin');
    a.style.cssText = 'padding:6px 14px;font-size:0.85rem;';
    wrapper.appendChild(a);
    const b = document.createElement('a');
    b.href = `signup.html${authSuffix}`;
    b.className = 'nav-link';
    b.textContent = 'Sign up';
    b.setAttribute('data-testid', 'nav-signup');
    wrapper.appendChild(b);
  }
  nav.appendChild(wrapper);
}

// ── Render loading / empty / error states ────────────────────
function renderLoading(container, msg = 'Searching for flights…') {
  container.innerHTML = `
    <div class="loading-spinner" data-testid="loading-state" role="status" aria-live="polite" aria-label="${msg}">
      <div class="spinner" aria-hidden="true"></div>
      <span>${msg}</span>
    </div>`;
}

function renderEmpty(container, title = 'No flights found', desc = 'Try adjusting your search.') {
  container.innerHTML = `
    <div class="empty-state" data-testid="no-results">
      <div class="empty-state-icon" aria-hidden="true">✈️</div>
      <h3 class="empty-state-title">${title}</h3>
      <p class="empty-state-desc">${desc}</p>
      <a href="/" class="btn btn-primary" data-testid="btn-back-home">New search</a>
    </div>`;
}

function renderError(container, msg = 'Something went wrong. Please try again.') {
  container.innerHTML = `
    <div class="empty-state" data-testid="error-state">
      <div class="empty-state-icon" aria-hidden="true">⚠️</div>
      <h3 class="empty-state-title">Error</h3>
      <p class="empty-state-desc">${msg}</p>
      <a href="/" class="btn btn-primary" data-testid="btn-back-home-error">Back to search</a>
    </div>`;
}
